float pi = 3.1415926598;
float speedOfSound = 343.0;
vec2 scale = vec2(100,100);//pixel distance / world distance (how many pixels needed to move 1 unit in world space)
float scale2 = 1.0;
int sourcesCount = 200;


float wave(float time, vec2 pos, vec2 source, float frequency, float phase, float amplitude){
    float dist = length(pos - source);
    return amplitude * cos(2.0 * pi * frequency * (dist / speedOfSound - time) - phase ) / (4.0 * pi * dist * dist + 1.0);
}

float wave2(float time, vec2 pos, vec2 source, vec2 target, float frequency, float phase, float amplitude){
    float dist = length(source - target);
    return wave(time, pos, source, frequency, 2.0 * pi * frequency / speedOfSound * dist + phase, amplitude * (4.0 * pi * dist * dist + 1.0));
}


vec2 toWorld(vec2 screen){
    return (screen - iResolution.xy * 0.5) / (scale * scale2);
}

vec2 toScreen(vec2 world){
    return world * (scale * scale2) + iResolution.xy * 0.5;
}


float lines(vec2 world){
    float o = 0.0;
    if(mod(world.x, 1.0) < 0.01 / scale2 || mod(world.y, 1.0) < 0.01 / scale2){
        o = 1.0;
    }

    return o;
}

vec3 applyLines(vec3 col, vec2 pos){
    if(lines(pos) > 0.0){
        //col = vec3(0, 0, 1);
        col += vec3(0,1,0) * 0.25 * ((1.0 - col) - col);
    }
    return col;
}


//t ranges from [-1, 1]
//Parabola
vec2 sourceFunc1(float t){
    return vec2(t * t - 1.0, t);
}

//line
vec2 sourceFunc2(float t){
    return vec2(0, t);
}

//Circle
vec2 sourceFunc3(float t){
    t += 1.0;
    t *= float(sourcesCount - 1) / float(sourcesCount);
    return vec2(cos(pi * t), sin(pi * t));
}

//Origin
vec2 sourceFunc4(float t){
    return vec2(0,0);
}

vec2 getSource(int n){
    float t = 2.0*float(n) / float(sourcesCount - 1) - 1.0;
    return 5.0 * sourceFunc3(t);
}


float amp(vec2 pos, vec2 target, float frequency, float amplitude){
    float amp1 = 0.0;
    for(int i = 0; i < sourcesCount; i++){
        amp1 += wave2(0.0, pos, getSource(i), target, frequency, 0.0, amplitude);
    }
    amp1 /= float(sourcesCount);

    float amp2 = 0.0;
    for(int i = 0; i < sourcesCount; i++){
        amp2 += wave2(0.0, pos, getSource(i), target, frequency, pi / 2.0, amplitude);
    }
    amp2 /= float(sourcesCount);

    return sqrt(amp1 * amp1 + amp2 * amp2);
}

float wave3(vec2 pos, vec2 target, float frequency, float amplitude, float deltaTime){
    float amp1 = 0.0;
    for(int i = 0; i < sourcesCount; i++){
        amp1 += wave2(iTime * deltaTime, pos, getSource(i), target, frequency, 0.0, amplitude);
    }

    return abs(amp1);
}




void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 pos = toWorld(fragCoord);
    vec2 target = toWorld(iMouse.xy);

    float frequency = 1000.0;
    float amplitude = 1.0;

    // Time varying pixel color

    vec3 col = vec3(0,0,0);
    bool isAmp = true;
    //float amp = wave2(iTime, pos, vec2(0,0), target, 1.0) + wave2(iTime, pos, vec2(0,1), target, 1.0);
    if(isAmp){
        float value = amp(pos, target, frequency, amplitude);
        col = vec3(1,1,1) * value;
        //if(value > 0.5){
        //    col = vec3(1,1,0) * value;
        //}else{
        //    col = vec3(0,1,1) * value;
        //}
    }else{
        float value = wave3(pos, target, frequency, amplitude, 0.01);
        col = vec3(1,1,1) * value;
    }




    col = applyLines(col, pos);

    if(length(toScreen(pos) - toScreen(target)) < max(5.0 * scale2, 1.0)){
        col = vec3(1, 0, 0);
    }
    for(int i = 0; i < sourcesCount; i++){
        if(length(toScreen(getSource(i)) - fragCoord) < max(5.0 * scale2, 1.0)){
            col = vec3(0, 0, 1);
        }
    }



    //col = vec3(1,1,1) * pow(fragCoord.x / iResolution.x, 2.2);
    // Output to screen
    fragColor = vec4(col,1.0);
}
